sealed class OrderChannelAdapter(ServiceBusSender sender, ServiceBusProcessor processor)
    : IOrderPublisher
{
    public Task PublishAsync(Order o, CancellationToken ct) =>
        sender.SendMessageAsync(new ServiceBusMessage(JsonSerializer.Serialize(o)), ct);
    public async Task StartAsync(Func<Order, Task> handler, CancellationToken ct)
    {
        processor.ProcessMessageAsync += a => handler(JsonSerializer.Deserialize<Order>(a.Message.Body)!);
        processor.ProcessErrorAsync += a => Task.CompletedTask;
        await processor.StartProcessingAsync(ct);
    }
}
